'use strict';
const $=s=>document.querySelector(s);const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const eras={2004:{phrase:'好久不见，2004。',sub:'那时的网页很慢，日子却很长。',memo:'拨号声响起，世界就从这块小小的屏幕开始了。',topics:[['当时的体育版面','sports.sina.com.cn'],['超级女声的第一年','ent.sina.com.cn'],['属于你的个人主页','www.blogcn.com']]},2005:{phrase:'你好，2005。',sub:'一首歌，一篇帖子，一个通宵。',memo:'在论坛里认识的朋友，可能从没见过面，却聊过整个人生。',topics:[['2005 年的娱乐版面','ent.sina.com.cn'],['博客时代的日常','www.blogcn.com'],['那时的游戏世界','games.sina.com.cn']]},2008:{phrase:'又见面了，2008。',sub:'熟悉的首页，藏着一整年的记忆。',memo:'你记得那个夏天吗？所有人的目光，都望向同一个地方。',topics:[['北京奥运会专题入口','2008.sina.com.cn'],['那一年的新闻','news.sina.com.cn'],['数码爱好者的讨论','www.pconline.com.cn']]},2010:{phrase:'久违了，2010。',sub:'旧的书签里，有年轻的自己。',memo:'博客还在更新，论坛依然热闹。我们开始把心情写得越来越短。',topics:[['南非世界杯','sports.sina.com.cn'],['博客与微博之间','t.sina.com.cn'],['豆瓣上的书影音','www.douban.com']]},2018:{phrase:'再逛一次，2018。',sub:'有些昨天，已经成为历史。',memo:'后来才发现，那些随手收藏的网页，也是一种时间胶囊。',topics:[['俄罗斯世界杯','sports.sina.com.cn'],['2018 年的哔哩哔哩','www.bilibili.com'],['那一年的技术社区','www.v2ex.com']]}};
const categories=[{id:'portal',title:'新闻 · 门户',en:'NEWS & PORTALS',sites:[['新浪','www.sina.com.cn'],['搜狐','www.sohu.com'],['网易','www.163.com'],['人民网','www.people.com.cn'],['新华网','www.xinhuanet.com'],['中国新闻网','www.chinanews.com.cn']]},{id:'forum',title:'论坛 · 社区',en:'FORUMS & COMMUNITIES',sites:[['天涯社区','www.tianya.cn'],['猫扑大杂烩','www.mop.com'],['西祠胡同','www.xici.net'],['水木清华','www.smth.org'],['百度贴吧','post.baidu.com'],['榕树下','www.rongshuxia.com']]},{id:'life',title:'生活 · 发现',en:'LIFE & DISCOVERY',sites:[['hao123','www.hao123.com'],['中关村在线','www.zol.com.cn'],['太平洋电脑网','www.pconline.com.cn'],['中国博客网','www.blogcn.com'],['中国雅虎','cn.yahoo.com'],['硅谷动力','www.enet.com.cn']]}];
let date='2004-08-01',current={type:'home'},history=[],cursor=-1,requestId=0;let saved=[];try{saved=JSON.parse(localStorage.getItem('archaeo-bookmarks')||'[]');if(!Array.isArray(saved))saved=[]}catch{};

const mobileSkins={uc:{name:'UC 经典',mark:'UC',description:'橙色高光 · 九宫格导航 · 经典菜单'},opera:{name:'Opera Mini',mark:'O',description:'红黑工具栏 · 快速拨号 · 简洁列表'},original:{name:'考古原版',mark:'◉',description:'墨绿纸色 · 原创年代导航'}};
let preferences={skin:'uc',font:'standard',night:false};try{const p=JSON.parse(localStorage.getItem('archaeo-appearance')||'{}');if(p&&mobileSkins[p.skin])preferences.skin=p.skin;if(['standard','large'].includes(p.font))preferences.font=p.font;preferences.night=p.night===true}catch{}
function applyAppearance(){document.body.dataset.mobileSkin=preferences.skin;document.body.classList.toggle('mobile-large',preferences.font==='large');document.body.classList.toggle('mobile-night',preferences.night);$('#phone-mark').textContent=mobileSkins[preferences.skin].mark;$('#phone-name').textContent='考古 · '+mobileSkins[preferences.skin].name;$('#phone-tab-title').textContent=current.name||'时光首页';try{localStorage.setItem('archaeo-appearance',JSON.stringify(preferences))}catch{}}
function settings(){dialog('浏览器设置',`<div class="settings-heading"><span class="settings-logo">${mobileSkins[preferences.skin].mark}</span><div><b>找回熟悉的上网手感</b><small>外观选择只改变手机端，不改变历史日期。</small></div></div><h3 class="settings-label">浏览器皮肤</h3><div class="skin-options">${Object.entries(mobileSkins).map(([key,skin])=>`<button class="skin-option ${preferences.skin===key?'chosen':''}" data-skin="${key}" aria-pressed="${preferences.skin===key}"><span class="skin-preview ${key}"><i>${skin.mark}</i><span>▤ archaeo://home</span><em>▦ ▦ ▦<br>▦ ▦ ▦</em><small>‹　⌂　☰</small></span><strong>${skin.name}</strong><span>${skin.description}</span><b class="skin-check">${preferences.skin===key?'●':'○'}</b></button>`).join('')}</div><h3 class="settings-label">阅读设置</h3><label class="setting-row" for="reading-font"><span>页面字号<small>仅影响本应用内的手机页面</small></span><select id="reading-font"><option value="standard" ${preferences.font==='standard'?'selected':''}>标准</option><option value="large" ${preferences.font==='large'?'selected':''}>大字</option></select></label><label class="setting-row" for="reading-night"><span>夜间模式<small>护眼深色界面</small></span><input id="reading-night" type="checkbox" ${preferences.night?'checked':''}></label><button class="primary" id="finish-settings">完成设置</button><p class="settings-disclaimer">UC 与 Opera Mini 为风格参考，非官方产品，也不是某一版本的精确复刻。设置保存在当前设备。</p>`)}
function mobileMenu(){dialog('浏览器菜单',`<div class="phone-menu"><button data-menu-action="home"><span>⌂</span>时光首页</button><button data-menu-action="favorites"><span>☆</span>我的收藏</button><button data-menu-action="history"><span>◷</span>浏览记录</button><button data-menu-action="date"><span>▦</span>穿越日期</button><button data-menu-action="refresh"><span>⟳</span>刷新页面</button><button data-menu-action="settings"><span>⚙</span>浏览器设置</button><button data-scene="homeworld"><span>⌂</span>家园空间</button><button data-scene="garden"><span>❀</span>开心菜园</button><button data-scene="wutang"><span>武</span>精武堂闯关</button></div><div class="menu-foot">${mobileSkins[preferences.skin].name}风格 · ${date}</div>`)}
function mobileHome(){return `<section class="wap-home"><div class="wap-welcome"><b>时光导航</b><span>${date.replaceAll('-','.')} · 历史互联网</span></div><div class="wap-search"><span>⌕</span><button id="focus-address">输入旧网址，回到那一年…</button><button data-action="settings" aria-label="切换浏览器皮肤">换肤</button></div><nav class="nostalgia-channels"><button data-scroll-news>大事记</button><button data-scene="homeworld">家园</button><button data-scene="friends">朋友</button><button data-scene="garden">种菜</button><button data-scene="wutang">精武堂</button><button data-scene="novels">小说</button><a href="https://web.archive.org/web/${year()}*/http://www.mop.com/" data-site="www.mop.com" data-name="猫扑大杂烩">猫扑</a></nav><div class="wap-caption">常用网址<span>经典入口 · 存档覆盖以来源为准</span></div><div class="speed-dial">${[['新浪','www.sina.com.cn','新'],['网易','www.163.com','网'],['搜狐','www.sohu.com','狐'],['天涯','www.tianya.cn','涯'],['贴吧','post.baidu.com','贴'],['hao123','www.hao123.com','123']].map((x,i)=>`<a href="https://web.archive.org/web/${year()}*/http://${x[1]}/" data-site="${x[1]}" data-name="${x[0]}" class="dial dial-${i}"><b>${x[2]}</b><span>${x[0]}</span></a>`).join('')}</div><div class="wap-years"><span>穿越</span>${Object.keys(eras).map(y=>`<button data-year="${y}" class="${year()===y?'selected':''}">${y}</button>`).join('')}<button id="wap-more-date" aria-label="更多日期">…</button></div>${annualNewsMarkup('mobile')}<div class="wap-link-box"><div class="wap-caption">论坛 · 社区<span>那些聊不完的夜晚</span></div><div class="wap-site-links">${categories[1].sites.map(s=>siteLink(s[0],s[1])).join('')}</div></div><div class="wap-bottom"><button data-action="settings">⚙ 换个浏览器，换种心情</button><p>真实历史资料 · 不生成虚构新闻<br>考古浏览器 / ARCHAEO BROWSER</p></div></section>`}

function year(){return date.slice(0,4)}function era(){return eras[year()]||{phrase:`你好，${year()}。`,sub:'打开旧的书签，回到那个时候。',memo:'这里的时钟停在你选择的日期。网页存档可能不完整，但每一段留下的记录，都有它自己的时间。',topics:[['当时的新闻版面','news.sina.com.cn'],['当时的门户首页','www.163.com'],['当时的论坛','www.tianya.cn']]}}
function siteLink(name,url,extra=''){return `<a href="https://web.archive.org/web/${year()}*/http://${escapeHTML(url)}/" data-site="${escapeHTML(url)}" data-name="${escapeHTML(name)}">${escapeHTML(name)}${extra}</a>`}
function renderHome(){const e=era();return `${mobileHome()}<div class="portal"><div class="portal-topline"><span>欢迎回来，远方的网友。</span><span class="online">● 时光连接已建立 · ${year()}</span></div><header class="portal-head"><div class="wordmark"><div class="logo" aria-hidden="true"></div><div><div class="brand">考古浏览器</div><div class="brand-en">ARCHAEO BROWSER</div></div></div><div class="tagline">在地址栏输入一个网址，<br>在时间里找回一段记忆。</div><div class="head-date"><b>${year()}</b><small>THE INTERNET, THEN.</small></div></header><nav class="portal-nav"><button class="active" data-action="home">时光首页</button><button data-section="portal">新闻门户</button><button data-section="forum">论坛社区</button><button data-section="life">个人天地</button><button data-action="favorites">我的收藏</button></nav><div class="welcome-strip"><span>✉ 欢迎来到过去。<b> 今天，你想回到哪一年？</b></span><span>EST. IN MEMORIES / 001</span></div><section class="era-hero"><div class="hero-copy"><div class="eyebrow">A SMALL WINDOW TO A BIG PAST</div><h1>${e.phrase}</h1><p>${e.sub}<br>时间停在 ${date.replaceAll('-','.')}，从一个旧网址开始。</p><div class="hero-stamp">${year()}</div></div><div class="hero-side" aria-hidden="true"><div class="hero-sky"></div><div class="cloud"></div><div class="hill"></div><div class="hill two"></div><div class="little-window"><div class="little-title">hello_world.txt <span style="float:right">×</span></div><div class="little-body">Connecting to...<br><b>the good old days.</b><br><span style="color:#8d9a72">[ connection found ]</span></div></div><div class="hero-side-label">SOMEWHERE IN YOUR MEMORY</div></div></section><div class="year-selector"><span>选择你的年代 →</span>${Object.keys(eras).map(y=>`<button data-year="${y}" class="${year()===y?'active':''}" aria-pressed="${year()===y}">${y}</button>`).join('')}</div>${annualNewsMarkup('desktop')}<div class="columns"><aside class="left-col"><section class="box"><h2>☆ 旧日常用站 <span>BOOKMARKS</span></h2><div class="site-list">${[['新浪首页','www.sina.com.cn','sina.com.cn'],['网易首页','www.163.com','163.com'],['搜狐首页','www.sohu.com','sohu.com'],['天涯社区','www.tianya.cn','tianya.cn'],['hao123 导航','www.hao123.com','hao123.com']].map((s,i)=>`<div class="site-row"><span class="number">0${i+1}</span>${siteLink(s[0],s[1])}<span class="domain">${s[2]}</span></div>`).join('')}</div></section><section class="box"><h2>▤ 考古须知 <span>READ ME</span></h2><p class="note">这里的链接通往<strong>真实历史存档</strong>。<br>首页是我们重制的年代导航，<strong>并非历史原页</strong>。<br>有些图片和帖子已经遗失。缺失，也是历史的一部分。<br><a href="#" data-action="about">了解存档来源 →</a></p></section><div class="text-ad"><b>慢一点，上网。</b><small>TAKE YOUR TIME ONLINE</small></div></aside><div class="center-col"><h2 class="section-title">◇ 那一年的互联网 <span>EXPLORE THE OLD WEB</span></h2>${categories.map(c=>{let sites=c.sites;if(year()==='2018'&&c.id==='forum')sites=[['天涯社区','www.tianya.cn'],['百度贴吧','tieba.baidu.com'],['豆瓣','www.douban.com'],['V2EX','www.v2ex.com'],['知乎','www.zhihu.com'],['哔哩哔哩','www.bilibili.com']];return `<section class="category-block" id="${c.id}"><div class="category-label">${c.title}<span>${c.en}</span></div><div class="link-grid">${sites.map((s,i)=>siteLink(s[0],s[1],c.id==='forum'&&i===0?'<em>HOT</em>':'')).join('')}</div></section>`}).join('')}</div><aside class="right-col"><div class="memory-card"><h3>一小片回忆</h3><p>${e.memo}</p><small>— 编者手记 / ${year()}</small></div><section class="box"><h2>↗ 年代探索 <span>TIME CAPSULE</span></h2><div class="topic-list">${e.topics.map(t=>`<div>${siteLink(t[0],t[1])}<small>${year()} · 主题站点入口</small></div>`).join('')}</div><p class="note" style="border-top:1px solid #d9dccd;font-size:10px">编辑选题，非历史新闻标题。<br>点击查找所选年份的真实页面。</p></section></aside></div><footer class="portal-foot"><div><button data-action="about">关于考古浏览器</button>·<button data-action="sources">资料来源</button>·<button data-action="install">添加到手机主屏幕</button></div><div>本站不属于过去，但希望帮你找到过去。 &nbsp; 最佳浏览心情：有一点怀念。</div><div>你的本机探索足迹 <span class="counter" id="counter">${String(history.filter(x=>x.page.type==='archive').length).padStart(5,'0').split('').map(x=>`<i>${x}</i>`).join('')}</span></div></footer></div>`}
function setTheme(){applyAppearance();document.body.classList.toggle('era-modern',Number(year())>=2010);$('#timeLabel').textContent=date.replaceAll('-','.');document.documentElement.style.setProperty('--chrome',Number(year())>=2010?'#e8ebe5':'#ece9d8')}
function navigate(page,push=true){requestId++;current=page;setTheme();if(push){history=history.slice(0,cursor+1);history.push({page:{...page},date});cursor=history.length-1}$('#content').innerHTML=page.type==='home'?renderHome():page.type==='scene'?renderScene(page):archivePage(page);$('#address').value=page.type==='home'?'archaeo://home':page.url;$('#windowtitle').textContent=page.type==='home'?'时光首页':page.name;$('#phone-tab-title').textContent=page.type==='home'?'时光首页':page.name;$('#status').textContent=page.type==='home'?'✓ 完成':'◷ 等待历史存档';document.title=`${page.type==='home'?'时光首页':page.name} · ${year()} — 考古浏览器`;updateNav();window.scrollTo({top:0,behavior:'instant'});if(page.type==='archive')resolveSnapshot(page,requestId)}
function updateNav(){for(const id of ['back','mback'])$('#'+id).disabled=cursor<=0;for(const id of ['forward','mforward'])$('#'+id).disabled=cursor>=history.length-1}
function move(n){const next=cursor+n;if(next<0||next>=history.length)return;cursor=next;date=history[cursor].date;navigate(history[cursor].page,false)}
function archivePage(p){const calendar=`https://web.archive.org/web/${year()}*/${p.url}`;return `<section class="archive-view"><div class="archive-kicker">HISTORICAL WEB / ${year()}</div><h1>${escapeHTML(p.name)}</h1><p class="archive-url">${escapeHTML(p.url)}</p><span class="source-pill">SOURCE: INTERNET ARCHIVE / WAYBACK MACHINE</span><div class="archive-info" id="archive-result">◷ 正在查询 ${date} 及之前、同一年内的最近快照……</div><div class="archive-actions"><a class="primary" href="${escapeHTML(calendar)}" target="_blank" rel="noopener noreferrer">在存档日历中查看 ${year()} 年 ↗</a><button class="secondary" id="savebookmark">☆ 收藏这个时间坐标</button></div><p class="archive-note">当前版本提供真实存档查询与跳转。完整历史网页在来源网站打开；其链接和图片可能使用其他日期的快照，请以来源时间栏为准。未找到合适快照时，我们不会用今天的页面代替。</p><div id="snapshot-actions"></div><div style="margin-top:30px;border-top:1px solid #d5d7c9;padding-top:18px"><button class="secondary" data-action="home">⌂ 回到时光首页</button><button class="secondary" id="retry" style="margin-left:8px">⟳ 重新查询</button></div></section>`}
async function resolveSnapshot(p,id){try{const cutoff=date.replaceAll('-','')+'235959';const endpoint=new URL('https://archive.org/wayback/available');endpoint.searchParams.set('url',p.url);endpoint.searchParams.set('timestamp',cutoff);const response=await fetch(endpoint,{signal:AbortSignal.timeout(8500)});if(!response.ok)throw Error('unavailable');const data=await response.json();if(id!==requestId)return;const snap=data.archived_snapshots?.closest;if(!snap||!snap.available){$('#archive-result').textContent='没有查到可用快照。你仍可以打开该年份的存档日历，检查其他地址或日期。';return}if(!/^\d{14}$/.test(snap.timestamp)||snap.timestamp>cutoff||!snap.timestamp.startsWith(year())){$('#archive-result').textContent='返回的最近快照不在所选年份或晚于目标日期，已跳过。请到存档日历选择实际可用的日期。';return}const u=new URL(snap.url);if(u.hostname!=='web.archive.org')throw Error('invalid-source');u.protocol='https:';const stamp=snap.timestamp;$('#archive-result').textContent=`✓ 找到真实快照：${stamp.slice(0,4)}-${stamp.slice(4,6)}-${stamp.slice(6,8)} ${stamp.slice(8,10)}:${stamp.slice(10,12)} UTC。目标日期：${date}；存档时间与目标日期可能不同。`;const link=document.createElement('a');link.className='primary';link.href=u.href;link.target='_blank';link.rel='noopener noreferrer';link.textContent='打开已核验日期的历史快照 ↗';$('#snapshot-actions').append(link);$('#status').textContent='✓ 已找到历史快照'}catch(e){if(id!==requestId)return;$('#archive-result').textContent='暂时无法连接存档查询服务。可打开上方存档日历继续查找；当前未核验具体快照是否存在。';$('#status').textContent='存档查询暂不可用 · 可使用日历入口'}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function dialog(title,html){$('#dialogtitle').textContent=title;$('#dialogbody').innerHTML=`<div class="dialog-content">${html}</div>`;if(!$('#modal').open)$('#modal').showModal()}
function dateDialog(){dialog('◷ 选择你的时间坐标',`<p>选一个日期，重新走进那时的互联网。浏览器会优先查找同一年、目标日期之前的快照。</p><label for="traveldate">想回到哪一天？</label><input id="traveldate" type="date" min="1996-01-01" max="2025-12-31" value="${date}"><button class="primary" id="applydate">进入那个年代 →</button><p style="font-size:10px;color:#87917a;margin-top:13px">网页快照使用所选日期；大事记按全年回顾。手机可在设置中切换 UC、Opera Mini 等复古风格。</p>`)}
function applyDate(d){if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||d<'1996-01-01'||d>'2025-12-31'){toast('请选择 1996 至 2025 年的有效日期');return}if(new Date(d+'T12:00:00Z').toISOString().slice(0,10)!==d){toast('这个日期不存在，请重新选择');return}date=d;$('#modal').close();navigate(current);toast(`已回到 ${date.replaceAll('-','.')}`)}
function favorites(){dialog('☆ 我的时光收藏',saved.length?`<p>保存在这台设备上，每一条都带着当时的日期。</p>${saved.map((s,i)=>`<div class="saved-row"><a href="#" data-bookmark="${i}">${escapeHTML(s.name)}<small>${escapeHTML(s.date)} · ${escapeHTML(s.url)}</small></a><button data-delete="${i}" aria-label="删除收藏">×</button></div>`).join('')}`:'<p>还没有收藏。打开一个历史网址，点击「收藏这个时间坐标」，把它留在这里。</p>')}
function action(a){if(a==='settings')settings();if(a==='mobilemenu')mobileMenu();if(a==='home')navigate({type:'home'});if(a==='favorites')favorites();if(a==='refresh')navigate(current,false);if(a==='history')dialog('◷ 本次探索记录',history.length?history.map((h,i)=>`<div class="saved-row"><a href="#" data-history="${i}">${escapeHTML(h.page.name||'时光首页')}<small>${h.date}</small></a></div>`).join(''):'还没有记录');if(a==='fullscreen'){if(!document.fullscreenElement&&document.documentElement.requestFullscreen)document.documentElement.requestFullscreen().catch(()=>toast('此设备不支持全屏'));else if(document.exitFullscreen)document.exitFullscreen().catch(()=>{})}if(a==='about'||a==='sources')dialog(a==='about'?'关于考古浏览器':'历史资料来源',`<p><b>考古浏览器 / FIRST EDITION</b><br>选择一个年份，重新走进那时的互联网。</p><p>浏览器外壳与首页为年代风格重制；站点链接指向 Internet Archive 的真实存档。这里没有生成的历史新闻，也不保证候选站点每年都有存档。</p><p><a href="https://web.archive.org/" target="_blank" rel="noopener noreferrer">Wayback Machine ↗</a> · 快照查询与历史页面<br><a href="https://commoncrawl.org/overview" target="_blank" rel="noopener noreferrer">Common Crawl ↗</a> · 后续可扩展的数据源，尚未接入</p><p>第一版：日期选择、网址查询、跨年份导航、本机收藏、iPhone 适配。外部存档内的后续跳转由来源网站控制，当前不能保证整段浏览严格停留在同一天。</p>`);if(a==='install')dialog('在 iPhone 上使用',`<p>用 <b>Safari</b> 打开本站，点击「分享」，选择「添加到主屏幕」，即可从桌面图标进入。</p><p>这是适配 iPhone 的网页应用，支持安全区和底部触控导航。历史存档仍需要网络连接。</p><p style="color:#87917a">收藏仅保存在当前设备的浏览器中。不同浏览器或主屏幕应用之间可能不共享数据。</p>`)}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.dataset.skin){preferences.skin=el.dataset.skin;applyAppearance();settings()}if(el.dataset.menuAction){$('#modal').close();if(el.dataset.menuAction==='date')dateDialog();else action(el.dataset.menuAction)}if(el.id==='finish-settings'){$('#modal').close();toast('已保存浏览器外观')}if(el.id==='focus-address'){$('#address').focus();$('#address').select();window.scrollTo({top:0,behavior:'smooth'})}if(el.id==='wap-more-date')dateDialog();if(el.dataset.action){e.preventDefault();action(el.dataset.action)}if(el.dataset.site){e.preventDefault();navigate({type:'archive',name:el.dataset.name,url:'http://'+el.dataset.site+'/'})}if(el.dataset.year){applyDate(el.dataset.year+date.slice(4))}if(el.dataset.section){const target=$('#'+el.dataset.section);if(target)target.scrollIntoView({behavior:'smooth',block:'center'})}if(el.dataset.bookmark!==undefined){e.preventDefault();const s=saved[Number(el.dataset.bookmark)];if(s){date=s.date;$('#modal').close();navigate({type:'archive',url:s.url,name:s.name})}}if(el.dataset.delete!==undefined){saved.splice(Number(el.dataset.delete),1);persist();favorites()}if(el.dataset.history!==undefined){e.preventDefault();cursor=Number(el.dataset.history);date=history[cursor].date;$('#modal').close();navigate(history[cursor].page,false)}if(el.id==='applydate')applyDate($('#traveldate').value);if(el.id==='savebookmark'){if(saved.some(s=>s.url===current.url&&s.date===date))return toast('这个时间坐标已在收藏夹');saved.push({url:current.url,name:current.name,date});persist();toast('已收藏这个时间坐标')}if(el.id==='retry')navigate(current,false)});
function persist(){try{localStorage.setItem('archaeo-bookmarks',JSON.stringify(saved))}catch{toast('设备无法保存收藏，请检查浏览器存储设置')}}
$('#addressform').addEventListener('submit',e=>{e.preventDefault();const v=$('#address').value.trim();if(v==='archaeo://home'||v===''){navigate({type:'home'});return}if(v.startsWith('archaeo://')&&sceneNames[v.slice('archaeo://'.length)]){openScene(v.slice('archaeo://'.length));return}try{const u=new URL(/^https?:\/\//i.test(v)?v:'http://'+v);if(!['http:','https:'].includes(u.protocol)||!u.hostname.includes('.')||u.username||u.password)throw Error();u.hash='';navigate({type:'archive',name:u.hostname,url:u.href})}catch{toast('请输入有效网址，例如 www.sina.com.cn')}});
document.addEventListener('change',e=>{if(e.target.id==='reading-font'){preferences.font=e.target.value;applyAppearance()}if(e.target.id==='reading-night'){preferences.night=e.target.checked;applyAppearance()}});
$('#closedialog').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});$('#datebutton').onclick=dateDialog;$('#mdate').onclick=dateDialog;$('#back').onclick=()=>move(-1);$('#mback').onclick=()=>move(-1);$('#forward').onclick=()=>move(1);$('#mforward').onclick=()=>move(1);function clock(){$('#localclock').textContent=new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false})}clock();setInterval(clock,60000);navigate({type:'home'});
